      vtablecallbackinterfaceeventlistener::cleanup();
  uniffi::matrix_ffi::cb::callbackinterfaceeventlistenermethod0::
      vtablecallbackinterfaceeventlistener::cleanup();
  uniffi::matrix_ffi::cb::callbackinterfaceclone::
      vtablecallbackinterfacenativesecrets::cleanup();
